# frozen_string_literal: true
#
# fake_fs.rb - the board's file system for an app under host Ruby.
#
# While a scene runs, File and Dir calls on the board's absolute paths
# (/app/..., /home/..., /etc/...) are answered from two layers:
#
#   overlay  a fresh directory per run (writes land here; the scene seeds
#            /home and /etc into it, and /etc/system_conf.toml is the
#            target's config file)
#   base     the git-tracked files under flash/ (read only), so untracked
#            local files (flash/app/usr, flash/etc/*.toml generated by the
#            build, flash/home) never make a record differ between machines
#
# The host's own paths (this repository, the overlay, Ruby's library) pass
# through untouched, so the harness itself is not redirected.
require "fileutils"
require "tmpdir"
require "rbconfig"

module Regress
  module FakeFS
    BASE_DIRS = %w[/app /usr /lib /bin /boot /var].freeze

    class << self
      attr_reader :root, :core
      attr_accessor :active

      # tracked: the git-tracked paths under flash/ ("flash/app/x.rb" ...).
      def setup(core, overlay, tracked)
        @core = core
        @root = overlay
        @tracked = {}
        @dirs = {}
        tracked.each do |t|
          dev = t.sub(%r{\Aflash}, "")
          @tracked[dev] = true
          d = File.dirname(dev)
          until d == "/" || d == "."
            @dirs[d] = true
            d = File.dirname(d)
          end
        end
        @deleted = {}
        @pass = [core, overlay, Dir.tmpdir, RbConfig::CONFIG["rubylibprefix"].to_s].reject(&:empty?)
        @active = false
      end

      def device?(p)
        return false unless @active && p.is_a?(String) && p.start_with?("/")
        @pass.none? { |h| p == h || p.start_with?(h + "/") }
      end

      def norm(p)
        File.expand_path(p, "/")
      end

      def over(p)
        File.join(@root, p)
      end

      def base_ok?(p)
        BASE_DIRS.any? { |d| p == d || p.start_with?(d + "/") } && !p.start_with?("/app/usr")
      end

      def base_file?(p)
        base_ok?(p) && @tracked[p] && !@deleted[p]
      end

      def base_dir?(p)
        base_ok?(p) && @dirs[p] && !@deleted[p]
      end

      # Host path to read p from (nil when it is not there).
      def read_path(p)
        p = norm(p)
        o = over(p)
        return o if Real.exist?(o)
        return File.join(@core, "flash", p) if base_file?(p)
        nil
      end

      # Host path to write p to (its directory made in the overlay).
      def write_path(p)
        p = norm(p)
        o = over(p)
        FileUtils.mkdir_p(Real.dirname(o))
        @deleted.delete(p)
        o
      end

      def exist?(p)
        p = norm(p)
        Real.exist?(over(p)) || base_file?(p) || base_dir?(p) || p == "/"
      end

      def directory?(p)
        p = norm(p)
        Real.directory?(over(p)) || base_dir?(p) || p == "/"
      end

      def file?(p)
        p = norm(p)
        Real.file?(over(p)) || base_file?(p)
      end

      def children(p)
        p = norm(p)
        raise Errno::ENOENT, p unless directory?(p)
        names = {}
        o = over(p)
        Real.children(o).each { |n| names[n] = true } if Real.directory?(o)
        if base_ok?(p) || p == "/"
          pre = p == "/" ? "/" : p + "/"
          (@tracked.keys + @dirs.keys).each do |t|
            next unless t.start_with?(pre) && base_ok?(t) && !@deleted[t]
            rest = t[pre.length..]
            names[rest.split("/")[0]] = true unless rest.empty?
          end
        end
        names.keys.sort
      end

      def delete(p)
        p = norm(p)
        o = over(p)
        found = false
        if Real.exist?(o)
          Real.delete_file(o)
          found = true
        end
        if base_file?(p)
          @deleted[p] = true
          found = true
        end
        raise Errno::ENOENT, p unless found
        1
      end

      def mkdir(p)
        p = norm(p)
        FileUtils.mkdir_p(over(p))
        @deleted.delete(p)
        0
      end

      def rmdir(p)
        p = norm(p)
        o = over(p)
        Real.rmdir(o) if Real.directory?(o)
        @deleted[p] = true if base_dir?(p)
        0
      end

      # Seeds a file into the overlay (scene setup).
      def seed(p, text)
        File.open(write_path(p), "wb") { |f| f.write(text) }
      end
    end

    # The original methods, for the overlay's own work.
    module Real
      class << self
        def exist?(p) = File.__regress_exist?(p)
        def directory?(p) = File.__regress_directory?(p)
        def file?(p) = File.__regress_file?(p)
        def dirname(p) = File.dirname(p)
        def delete_file(p) = File.__regress_delete(p)
        def children(p) = Dir.__regress_children(p)
        def rmdir(p) = Dir.__regress_rmdir(p)
      end
    end
  end
end

class << File
  alias_method :__regress_exist?, :exist?
  alias_method :__regress_directory?, :directory?
  alias_method :__regress_file?, :file?
  alias_method :__regress_delete, :delete
  alias_method :__regress_open, :open
  alias_method :__regress_size, :size
  alias_method :__regress_read, :read
  alias_method :__regress_binread, :binread
  alias_method :__regress_rename, :rename
  alias_method :__regress_stat, :stat
  alias_method :__regress_mtime, :mtime

  def exist?(p) = Regress::FakeFS.device?(p) ? Regress::FakeFS.exist?(p) : __regress_exist?(p)
  def directory?(p) = Regress::FakeFS.device?(p) ? Regress::FakeFS.directory?(p) : __regress_directory?(p)
  def file?(p) = Regress::FakeFS.device?(p) ? Regress::FakeFS.file?(p) : __regress_file?(p)

  def open(p, mode = "r", *rest, **kw, &blk)
    return __regress_open(p, mode, *rest, **kw, &blk) unless Regress::FakeFS.device?(p)
    m = mode.to_s
    host = if m.start_with?("w") || m.start_with?("a") || m.include?("+")
             # Appending to (or updating) a base file starts from its copy.
             w = Regress::FakeFS.write_path(p)
             src = Regress::FakeFS.read_path(p)
             FileUtils.cp(src, w) if src && src != w && !m.start_with?("w")
             w
           else
             Regress::FakeFS.read_path(p) || raise(Errno::ENOENT, p)
           end
    __regress_open(host, mode, *rest, **kw, &blk)
  end

  def new(p, mode = "r", *rest, **kw)
    return super unless Regress::FakeFS.device?(p)
    open(p, mode, *rest, **kw)
  end

  def size(p)
    return __regress_size(p) unless Regress::FakeFS.device?(p)
    __regress_size(Regress::FakeFS.read_path(p) || raise(Errno::ENOENT, p))
  end

  def read(p, *rest, **kw)
    return __regress_read(p, *rest, **kw) unless Regress::FakeFS.device?(p)
    __regress_read(Regress::FakeFS.read_path(p) || raise(Errno::ENOENT, p), *rest, **kw)
  end

  def binread(p, *rest)
    return __regress_binread(p, *rest) unless Regress::FakeFS.device?(p)
    __regress_binread(Regress::FakeFS.read_path(p) || raise(Errno::ENOENT, p), *rest)
  end

  def delete(*ps)
    ps.each { |p| Regress::FakeFS.device?(p) ? Regress::FakeFS.delete(p) : __regress_delete(p) }
    ps.size
  end
  alias_method :unlink, :delete

  def rename(a, b)
    return __regress_rename(a, b) unless Regress::FakeFS.device?(a)
    src = Regress::FakeFS.read_path(a) || raise(Errno::ENOENT, a)
    dst = Regress::FakeFS.write_path(b)
    FileUtils.cp(src, dst)
    Regress::FakeFS.delete(a)
    0
  end

  def stat(p)
    return __regress_stat(p) unless Regress::FakeFS.device?(p)
    host = Regress::FakeFS.read_path(p)
    host ||= File.join(Regress::FakeFS.core, "flash", Regress::FakeFS.norm(p)) if Regress::FakeFS.directory?(p)
    __regress_stat(host || raise(Errno::ENOENT, p))
  end

  # A fixed time: a record must not carry the checkout's mtimes.
  def mtime(p)
    return __regress_mtime(p) unless Regress::FakeFS.device?(p)
    raise Errno::ENOENT, p unless Regress::FakeFS.exist?(p)
    Time.at(1_792_900_000)
  end
end

class << Dir
  alias_method :__regress_children, :children
  alias_method :__regress_entries, :entries
  alias_method :__regress_exist?, :exist?
  alias_method :__regress_mkdir, :mkdir
  alias_method :__regress_rmdir, :rmdir
  alias_method :__regress_open, :open
  alias_method :__regress_glob, :glob

  def children(p, **kw) = Regress::FakeFS.device?(p) ? Regress::FakeFS.children(p) : __regress_children(p, **kw)
  def entries(p, **kw) = Regress::FakeFS.device?(p) ? [".", ".."] + Regress::FakeFS.children(p) : __regress_entries(p, **kw)
  def exist?(p) = Regress::FakeFS.device?(p) ? Regress::FakeFS.directory?(p) : __regress_exist?(p)
  def mkdir(p, *rest) = Regress::FakeFS.device?(p) ? Regress::FakeFS.mkdir(p) : __regress_mkdir(p, *rest)

  def rmdir(p) = Regress::FakeFS.device?(p) ? Regress::FakeFS.rmdir(p) : __regress_rmdir(p)
  alias_method :delete, :rmdir
  alias_method :unlink, :rmdir

  def open(p, *rest, **kw, &blk)
    return __regress_open(p, *rest, **kw, &blk) unless Regress::FakeFS.device?(p)
    d = Regress::FakeDir.new(p, Regress::FakeFS.children(p))
    return d unless blk
    blk.call(d)
  end

  def glob(pat, *rest, **kw, &blk)
    return __regress_glob(pat, *rest, **kw, &blk) unless pat.is_a?(String) && Regress::FakeFS.device?(pat)
    dir = File.dirname(pat)
    base = File.basename(pat)
    out = Regress::FakeFS.directory?(dir) ? Regress::FakeFS.children(dir).select { |n| File.fnmatch(base, n) }.map { |n| File.join(dir, n) } : []
    blk ? out.each(&blk) : out
  end
end

module Regress
  # Dir.open on a board path: the picoruby Dir's reading calls.
  class FakeDir
    include Enumerable

    def initialize(path, names)
      @path = path
      @names = names
      @i = 0
    end

    def read
      n = [".", ".."][@i] || @names[@i - 2]
      @i += 1
      n
    end

    def each(&blk)
      ([".", ".."] + @names).each(&blk)
      self
    end

    def each_child(&blk)
      @names.each(&blk)
      self
    end

    def children = @names.dup
    def close = nil
    def rewind = (@i = 0)
    def path = @path
  end
end
